import{_ as d,o as e,c as o,ag as a}from"./chunks/framework.BoXUJ6sC.js";const r="/beadv8_8_BBCC_BE/assets/22.BfJsOzgc.png",u=JSON.parse('{"title":"운영 · 모니터링","description":"","frontmatter":{},"headers":[],"relativePath":"planning/operations.md","filePath":"planning/operations.md"}'),c={name:"planning/operations.md"};function n(l,t,i,s,h,p){return e(),o("div",null,[...t[0]||(t[0]=[a('<h1 id="운영-·-모니터링" tabindex="-1">운영 · 모니터링 <a class="header-anchor" href="#운영-·-모니터링" aria-label="Permalink to &quot;운영 · 모니터링&quot;">​</a></h1><p>앱이 도는 EC2 한 대(dev · prod 공통) 안에 Prometheus · Loki · Alloy · Grafana 네 컨테이너가 함께 돕니다. 모두 127.0.0.1에만 열려 있고, 밖에서 볼 수 있는 모니터링 화면은 Nginx를 거친 Grafana(<code>grafana.kidly.kro.kr</code>) 하나입니다 (앱 API도 같은 Nginx를 거침). 장애는 <code>#4팀-운영이슈</code>, 배포 결과는 <code>#4팀-알림</code>으로 갑니다.</p><p>최종: 모니터링(Prometheus · Loki · Alloy · Grafana)은 Elasticsearch와 함께 t3.medium의 k3s로 옮겼습니다. 아래 그림과 10.1의 서버 배치는 세미 기준이고 인프라 담당(maruhxn)이 갱신합니다. 받는 쪽이 이벤트를 DLT로 보낼 때도 ERROR 로그를 남겨 ERROR 알림으로 알 수 있습니다.</p><p><img src="'+r+'" alt="Kidly 모니터링 구성도"></p><p>실선 색 = 흐름 (회색 요청 · 주황 메트릭 · 청록 로그 · 빨강 알림 · 보라 배포). nginx는 서버에 직접 설치하고, 밖에서 <code>/actuator</code>는 막고 <code>/actuator/health</code>만 엽니다.</p><h2 id="_10-1-흐름-네-가지" tabindex="-1">10.1 흐름 네 가지 <a class="header-anchor" href="#_10-1-흐름-네-가지" aria-label="Permalink to &quot;10.1 흐름 네 가지&quot;">​</a></h2><table tabindex="0"><thead><tr><th>흐름</th><th>내용</th></tr></thead><tbody><tr><td>메트릭</td><td>앱이 <code>/actuator/prometheus</code>에 JVM · HikariCP · HTTP 요청 · 로그 건수를 내놓고, Prometheus가 15초마다 가져가 15일 보관. 앱 배포가 성공하면 수집 대상 주소를 갱신. Grafana의 JVM · Spring Boot 대시보드와 알림 규칙이 씀</td></tr><tr><td>로그</td><td>앱은 콘솔(stdout)에 ECS JSON을 한 줄씩 쓰고, 요청마다 끝에 한 줄을 남김. Alloy가 docker에서 dev · prod 앱 로그를 읽어 env · level · service_name 라벨과 traceId · memberId를 붙이고, Loki가 14일 보관. Grafana Explore · Logs Drilldown에서 찾음</td></tr><tr><td>알림</td><td>Grafana가 알림 규칙 3개를 1분마다 확인. 걸리면 30초 동안 모아 보내고, 계속되면 4시간마다 다시 보냄. 풀리면 해결 메시지. 메시지에 규칙 보기 · 일시정지 링크, 5xx · ERROR에는 로그 보기 링크</td></tr><tr><td>배포</td><td>develop에 머지되면 앱은 <code>deploy</code>, <code>deploy/monitoring/**</code> 변경은 <code>monitoring-deploy</code> 워크플로가 돎. 앱 배포는 CI와 이미지 빌드가 모두 성공해야 서버에 올리고, 앱과 무관한 변경은 건너뜀. 둘 다 SSH로 서버의 <code>deploy.sh</code>를 실행하고, 비밀값은 Environment <code>dev</code> Secret에서 매번 새로 씀. <code>deploy-notify</code>가 결과를 <code>#4팀-알림</code>으로 보내고, 앱이 못 뜨면 로그에서 원인(Flyway 등)을 뽑아 붙임</td></tr></tbody></table><h2 id="_10-2-오는-알림" tabindex="-1">10.2 오는 알림 <a class="header-anchor" href="#_10-2-오는-알림" aria-label="Permalink to &quot;10.2 오는 알림&quot;">​</a></h2><table tabindex="0"><thead><tr><th>알림</th><th>언제</th><th>채널</th></tr></thead><tbody><tr><td>앱 다운</td><td>앱 메트릭을 2분 넘게 못 읽음</td><td><code>#4팀-운영이슈</code></td></tr><tr><td>5xx 증가</td><td>최근 5분 5xx 비율이 5% 넘음 (actuator 제외)</td><td><code>#4팀-운영이슈</code></td></tr><tr><td>ERROR 로그</td><td>최근 5분 ERROR 로그가 1건 이상</td><td><code>#4팀-운영이슈</code></td></tr><tr><td>배포 결과</td><td>앱 · 모니터링 배포가 끝날 때 (실패면 원인 로그 포함, GitHub Actions가 보냄)</td><td><code>#4팀-알림</code></td></tr></tbody></table><h2 id="_10-3-이럴-땐-여기서" tabindex="-1">10.3 이럴 땐 여기서 <a class="header-anchor" href="#_10-3-이럴-땐-여기서" aria-label="Permalink to &quot;10.3 이럴 땐 여기서&quot;">​</a></h2><table tabindex="0"><thead><tr><th>알고 싶은 것</th><th>볼 곳 (모두 Grafana 안)</th></tr></thead><tbody><tr><td>메모리 · GC · 스레드</td><td>대시보드 → Kidly → JVM</td></tr><tr><td>DB 커넥션 풀 · HTTP 처리량</td><td>대시보드 → Kidly → Spring Boot (HikariCP)</td></tr><tr><td>특정 URL · 상태 · 회원의 요청</td><td>Drilldown → Logs → kidly → Fields 칸에서 거르고 Table</td></tr><tr><td>한 요청의 로그 전부</td><td>표의 traceId → 같은 요청 로그 보기 (프론트는 응답 헤더 <code>X-Request-Id</code>로 찾음)</td></tr><tr><td>알림이 왜 왔나</td><td>Slack 메시지의 로그 보기</td></tr><tr><td>배포가 왜 실패했나</td><td><code>#4팀-알림</code> 메시지의 원인, 없으면 Actions 로그</td></tr><tr><td>검색 서비스 메트릭 · 로그</td><td>Grafana에서 job <code>kidly-search</code>, 로그 <code>service_name=kidly-search</code>. 앱 대시보드 · 알림(job <code>kidly</code>)과 섞이지 않음</td></tr><tr><td>Elasticsearch 상태</td><td>t3.medium에서 <code>kubectl -n search get pods</code>, <code>/_cluster/health</code>(yellow · green), <code>/_cat/indices</code>(<code>dev-products</code> · <code>dev-sellers</code>)</td></tr><tr><td>색인이 비었을 때</td><td>Elasticsearch를 새로 만들었거나 데이터를 지운 경우. 상품 · 판매자 전체 다시 보내기 API로 채움(#577)</td></tr><tr><td>검색이 503일 때</td><td>Elasticsearch 연결 · 과부하 · 색인 없음. 급하면 Gateway의 <code>KIDLY_SEARCH_URI</code>를 kidly-app으로 바꿔 상품의 기존 목록 API로 되돌림</td></tr><tr><td>이벤트가 처리되지 않을 때</td><td>Slack ERROR 알림 · 로그에서 <code>eventType</code> · <code>eventId</code> · 키로 찾기 → <code>{토픽}.{받는도메인}.dlt</code> 확인. 주문은 관리자 화면에서 DLT 재처리, 나머지는 K23</td></tr></tbody></table><h2 id="_10-4-운영-규칙-·-아직-볼-수-없는-것" tabindex="-1">10.4 운영 규칙 · 아직 볼 수 없는 것 <a class="header-anchor" href="#_10-4-운영-규칙-·-아직-볼-수-없는-것" aria-label="Permalink to &quot;10.4 운영 규칙 · 아직 볼 수 없는 것&quot;">​</a></h2><ul><li><strong>운영 규칙</strong>: 대시보드 · 알림 규칙은 레포(<code>deploy/monitoring</code>)에서만 고칩니다. Grafana 화면에서 고친 대시보드 · 알림 · 기본 열은 다음 배포 때 레포 파일 내용으로 돌아갑니다.</li><li><strong>로컬</strong>: 로컬 compose에도 Prometheus · Grafana가 있어 bootRun 앱 메트릭을 <code>env=local</code>로 봅니다 (대시보드는 운영과 같은 파일).</li><li><strong>아직 볼 수 없는 것</strong>: 로컬 앱 로그(텍스트 콘솔이라 Loki로 가지 않음), 스케줄러 · 비동기 작업의 traceId(요청이 아닌 작업에는 아직 없음), 14일보다 오래된 로그 · 15일보다 오래된 메트릭.</li></ul>',13)])])}const m=d(c,[["render",n]]);export{u as __pageData,m as default};
